/* ─────────────────────────────────────────
   KYRON BRAND PRINT OVERLAY on product images
───────────────────────────────────────── */
const BrandOverlay = ({ cat }) => {
  if (cat === "Jeans") {
    // Subtle leather patch on jeans
    return (
      <div style={{
        position:"absolute", bottom:16, right:12, zIndex:4,
        background:"rgba(10,10,10,0.9)", border:"1px solid rgba(212,43,43,0.6)",
        padding:"5px 12px", backdropFilter:"blur(4px)",
        display:"flex", alignItems:"center", gap:6,
      }}>
        <svg width="12" height="12" viewBox="0 0 12 12"><circle cx="6" cy="6" r="5" stroke="#D42B2B" strokeWidth="1" fill="none"/><text x="6" y="8.5" textAnchor="middle" fill="#D42B2B" fontFamily="'Bebas Neue',cursive" fontSize="5.5">K</text></svg>
        <span style={{fontFamily:"'Bebas Neue',cursive",fontSize:12,letterSpacing:3,color:"rgba(212,43,43,0.9)"}}>KYRON</span>
      </div>
    );
  }
  if (cat === "Caps") {
    // Embroidery badge on cap
    return (
      <div style={{
        position:"absolute", bottom:14, left:"50%", transform:"translateX(-50%)", zIndex:4,
        background:"rgba(212,43,43,0.95)", padding:"6px 18px",
      }}>
        <span style={{fontFamily:"'Bebas Neue',cursive",fontSize:14,letterSpacing:4,color:"#fff"}}>KYRON</span>
      </div>
    );
  }
  // T-Shirts & Shirts: large chest print
  const isTee = cat === "T-Shirts";
  return (
    <div style={{
      position:"absolute", inset:0, zIndex:4, pointerEvents:"none",
      display:"flex", alignItems:"center", justifyContent:"center",
    }}>
      <div style={{
        display:"flex", flexDirection:"column", alignItems:"center",
        opacity: isTee ? 0.95 : 0.82,
        filter:"drop-shadow(0 3px 12px rgba(0,0,0,0.85))",
        transform: isTee ? "translateY(-10%)" : "translateY(-8%)",
      }}>
        <KyronLogo size={isTee ? 90 : 68}/>
        <div style={{
          marginTop:2,
          fontFamily:"'Bebas Neue',cursive",
          fontSize: isTee ? 26 : 18,
          letterSpacing: 8,
          color:"#fff",
          textShadow:"0 0 24px rgba(212,43,43,0.9), 0 2px 8px rgba(0,0,0,1)",
          lineHeight:1,
        }}>KYRON</div>
        {isTee && (
          <div style={{
            fontFamily:"'Barlow Condensed',sans-serif",
            fontSize:9, letterSpacing:5,
            color:"rgba(212,43,43,0.95)",
            textTransform:"uppercase", marginTop:3,
            textShadow:"0 1px 4px rgba(0,0,0,0.9)",
          }}>STREETWEAR</div>
        )}
      </div>
    </div>
  );
};

