const ProductCard_Image = ({ product, onQuickView, onWish, wished }) => (
  <div style={{position:"relative", aspectRatio:"3/4", overflow:"hidden", background:"#111", cursor:"pointer"}} onClick={onQuickView}>
    <img
      src={getProductImg(product)}
      alt={product.name}
      loading="lazy"
      style={{position:"absolute",inset:0,width:"100%",height:"100%",objectFit:"cover",display:"block",transition:"transform 0.5s ease"}}
      onMouseOver={e=>e.currentTarget.style.transform="scale(1.05)"}
      onMouseOut={e=>e.currentTarget.style.transform="scale(1)"}
    />
    {/* Dark vignette */}
    <div style={{position:"absolute",inset:0,zIndex:2,background:"linear-gradient(160deg,rgba(0,0,0,0.1) 0%,rgba(0,0,0,0.45) 100%)",pointerEvents:"none"}}/>
    {/* KYRON brand overlay */}
    <BrandOverlay cat={product.cat}/>
    {/* Badge */}
    {product.badge && (
      <div style={{position:"absolute",top:14,left:14,zIndex:5}}>
        {product.badge==="NEW" && <span style={{background:"#F5F5F5",color:"#0A0A0A",fontSize:10,fontWeight:700,letterSpacing:2,padding:"5px 10px",textTransform:"uppercase"}}>New</span>}
        {product.badge==="DROP" && <span style={{background:"#D42B2B",color:"#fff",fontSize:10,fontWeight:700,letterSpacing:2,padding:"5px 10px",textTransform:"uppercase"}}>Drop</span>}
        {product.badge==="LTD" && <span style={{border:"1px solid #D42B2B",color:"#D42B2B",fontSize:10,fontWeight:700,letterSpacing:2,padding:"5px 10px",textTransform:"uppercase"}}>Ltd</span>}
      </div>
    )}
    {/* Hover overlay with buttons */}
    <div className="p-hover-overlay" style={{position:"absolute",inset:0,zIndex:6,background:"rgba(0,0,0,0.38)",opacity:0,transition:"opacity 0.3s",display:"flex",alignItems:"center",justifyContent:"center",gap:10}}>
      <button
        style={{background:"#D42B2B",color:"#fff",border:"none",padding:"11px 18px",fontFamily:"'Barlow Condensed',sans-serif",fontSize:13,fontWeight:700,letterSpacing:2,textTransform:"uppercase",cursor:"pointer"}}
        onClick={e=>{e.stopPropagation();onQuickView();}}>Quick View</button>
      <button
        style={{background:"rgba(10,10,10,0.85)",color:"#fff",border:"1px solid rgba(255,255,255,0.3)",padding:"11px",cursor:"pointer",fontSize:16,lineHeight:1}}
        onClick={e=>{e.stopPropagation();onWish();}}>
        {wished?"♥":"♡"}
      </button>
    </div>
  </div>
);

